import type { ChipProps } from "./chip.types";
import type { CSSObject, Theme } from "@emotion/react";
import type { ComponentStyleVariantConfig } from "@types";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

const componentName = "Chip";

export const ChipClasses = {
  root: "exp-textura_chip",
  sm: "exp-textura_chip_sm",
  outline: "exp-textura_chip_outline",
  closeButton: "exp-textura_chip_close_button",
  closeButtonOutline: "exp-textura_chip_close_button_outline",
  overflow: "exp-textura_chip_overflow",
  hasStartAdornment: "exp-textura_chip_has_start_adornment",
};

const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  critical: {
    root: {
      backgroundColor: theme.chip.subtle.critical.background,
      color: theme.chip.subtle.critical.content,
      borderColor: theme.chip.subtle.critical.border,
    },
    outline: {
      backgroundColor: theme.chip.outline.critical.background,
      color: theme.chip.outline.critical.content,
      borderColor: theme.chip.outline.critical.border,
    },
  },
  info: {
    root: {
      backgroundColor: theme.chip.subtle.info.background,
      color: theme.chip.subtle.info.content,
      borderColor: theme.chip.subtle.info.border,
    },
    outline: {
      backgroundColor: theme.chip.outline.info.background,
      color: theme.chip.outline.info.content,
      borderColor: theme.chip.outline.info.border,
    },
  },
  neutral: {
    root: {
      backgroundColor: theme.chip.subtle.neutral.background,
      color: theme.chip.subtle.neutral.content,
      borderColor: theme.chip.subtle.neutral.border,
    },
    outline: {
      backgroundColor: theme.chip.outline.neutral.background,
      color: theme.chip.outline.neutral.content,
      borderColor: theme.chip.outline.neutral.border,
    },
  },
  success: {
    root: {
      backgroundColor: theme.chip.subtle.success.background,
      color: theme.chip.subtle.success.content,
      borderColor: theme.chip.subtle.success.border,
    },
    outline: {
      backgroundColor: theme.chip.outline.success.background,
      color: theme.chip.outline.success.content,
      borderColor: theme.chip.outline.success.border,
    },
  },
  warning: {
    root: {
      backgroundColor: theme.chip.subtle.warning.background,
      color: theme.chip.subtle.warning.content,
      borderColor: theme.chip.subtle.warning.border,
    },
    outline: {
      backgroundColor: theme.chip.outline.warning.background,
      color: theme.chip.outline.warning.content,
      borderColor: theme.chip.outline.warning.border,
    },
  },
});

const generateStyles = (props: ChipProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<ChipProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "inline-flex",
    alignItems: "center",
    justifyContent: "center",
    cursor: "default",
    whiteSpace: "nowrap",
    width: "fit-content",
    borderRadius: theme.toRem(theme.border.radius.lg),
    border: `${theme.toRem(theme.border.width.sm)} solid ${theme.chip.subtle.attention.border}`,
    ...theme.typography.label.sm,
    gap: theme.toRem(theme.spacing[4]),
    height: theme.toRem(28),
    padding: `0 ${theme.toRem(theme.spacing[8])}`,
    backgroundColor: theme.chip.subtle.attention.background,
    color: theme.chip.subtle.attention.content,

    [`&.${ChipClasses.hasStartAdornment}`]: {
      paddingInlineStart: 0,
      borderInlineStartWidth: 0,
      [`&.${ChipClasses.sm}`]: {
        paddingInlineStart: 0,
        borderInlineStartWidth: 0,
        ...styleSlots?.hasStartAdornmentSm,
      },
      ...styleSlots?.hasStartAdornment,
    },

    [`&.${ChipClasses.overflow}`]: {
      backgroundColor: theme.chipStack.color.background,
      color: theme.chipStack.color.content,
      borderColor: theme.chipStack.color.border,
      padding: `0 ${theme.toRem(theme.spacing[12])}`,
      ...theme.typography.label.sm,
      lineHeight: theme.typography.lineHeight[16],
      cursor: "pointer",

      [`&.${ChipClasses.sm}`]: {
        height: theme.toRem(20),
        padding: `0 ${theme.toRem(theme.spacing[8])}`,
        ...theme.typography.micro.sm,
        ...styleSlots?.overflowSm,
      },
      ...styleSlots?.overflow,
    },

    [`&.${ChipClasses.outline}`]: {
      backgroundColor: theme.chip.outline.attention.background,
      borderColor: theme.chip.outline.attention.border,
      color: theme.chip.outline.attention.content,
      [`> .${ChipClasses.closeButtonOutline}`]: {
        color: theme.color.content.weak,
        ...styleSlots?.closeButtonOutline,
      },
      ...styleSlots?.outline,
    },

    [`&.${ChipClasses.sm}`]: {
      height: theme.toRem(20),
      padding: `0 ${theme.toRem(theme.spacing[8])}`,
      fontSize: theme.typography.micro.sm.fontSize,
      ...styleSlots?.sm,
    },

    [`> .${ChipClasses.closeButton}`]: {
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      cursor: "pointer",
      marginInlineEnd: theme.toRem(-2),
      fontSize: theme.toRem(12),
      color: theme.color.transparency.black[55],
      "&:focus-visible": {
        ...styleSlots?.closeButtonFocus,
      },
      ...styleSlots?.closeButton,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledChip = styled("span", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<ChipProps>((props) => generateStyles(props));
